.grille { display: grid; gap: 12px; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); }
.tuile { display: grid; place-items: center; min-height: 140px; background: #dfe5e2; border: 1px solid #c3cbd3; transition: transform 120ms ease; }
